# config.pbtxt for a TorchScript text classifier
name: "text_classifier"
backend: "pytorch"
max_batch_size: 64

dynamic_batching {
  preferred_batch_size: [ 16, 32, 64 ]
  max_queue_delay_microseconds: 5000
}

input [{
  name: "input_ids"
  data_type: TYPE_INT64
  dims: [ -1, 128 ]    # -1 = dynamic batch
}]

output [{
  name: "logits"
  data_type: TYPE_FP32
  dims: [ -1, 10 ]
}]

instance_group [{
  kind: KIND_GPU
  count: 2             # two concurrent model instances
}]

import bentoml

@bentoml.service(
    resources={"gpu": 1},
    traffic={"timeout": 10},
)
class SentimentClassifier:
    model_ref = bentoml.transformers.get("sentiment:latest")

    def __init__(self):
        import torch
        self.pipeline = self.model_ref.load_model()

    @bentoml.api
    def classify(self, text: str) -> dict:
        result = self.pipeline(text)[0]
        return {"label": result["label"], "score": result["score"]}

