# Custom TorchServe handler for a BERT text classifier
from ts.torch_handler.base_handler import BaseHandler
from transformers import AutoTokenizer, AutoModelForSequenceClassification
import torch

class TextClassifierHandler(BaseHandler):
    def initialize(self, context):
        self.model = AutoModelForSequenceClassification.from_pretrained(
            context.system_properties["model_dir"]
        ).eval().to(self.device)
        self.tokenizer = AutoTokenizer.from_pretrained(
            context.system_properties["model_dir"]
        )

    def preprocess(self, requests):
        texts = [r["body"]["text"] for r in requests]
        return self.tokenizer(texts, return_tensors="pt", padding=True, truncation=True)

    def inference(self, inputs):
        with torch.no_grad():
            return self.model(**inputs.to(self.device)).logits

    def postprocess(self, logits):
        return [{"class": int(torch.argmax(l)), "score": float(torch.max(l))} for l in logits]

