# Triton ensemble config: preprocessing → bert → ranker
name: "search_pipeline"
platform: "ensemble"
max_batch_size: 32

ensemble_scheduling {
  step [
    {
      model_name: "text_preprocessor"
      model_version: -1
      input_map  { key: "raw_text"   value: "raw_text" }
      output_map { key: "input_ids"  value: "input_ids"
                   key: "attn_mask"  value: "attn_mask" }
    },
    {
      model_name: "bert_embedder"
      model_version: -1
      input_map  { key: "input_ids"    value: "input_ids"
                   key: "attn_mask"    value: "attn_mask" }
      output_map { key: "cls_embedding" value: "embedding" }
    },
    {
      model_name: "ranker"
      model_version: -1
      input_map  { key: "embedding" value: "embedding" }
      output_map { key: "scores"   value: "final_scores" }
    }
  ]
}
